/* ── Reset & tokens ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #0f1117;
  --color-surface:      #1a1d27;
  --color-surface-2:    #22263a;
  --color-border:       #2e3348;
  --color-text:         #e8eaf0;
  --color-text-muted:   #8b90a7;
  --color-accent:       #6c63ff;
  --color-accent-hover: #574fdc;
  --color-danger:       #e5534b;
  --color-danger-hover: #c0392b;
  --color-danger-bg:    rgba(229, 83, 75, 0.12);
  --color-focus-ring:   #6c63ff;

  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.45);
  --shadow-dialog: 0 24px 64px rgba(0,0,0,0.7);

  --transition: 150ms ease;
}

/* ── Base ───────────────────────────────────────────────────── */
html { font-size: 16px; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.6;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus { top: 1rem; }

/* ── Layout ─────────────────────────────────────────────────── */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.app-header .logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
  text-decoration: none;
}

.app-header .logo svg { color: var(--color-accent); }

.header-actions { display: flex; gap: .75rem; align-items: center; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  line-height: 1;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

.btn-ghost {
  background: transparent;
  color: var(--color-text-muted);
  border-color: var(--color-border);
}
.btn-ghost:hover {
  background: var(--color-surface-2);
  color: var(--color-text);
  border-color: var(--color-accent);
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.btn-primary:hover { background: var(--color-accent-hover); border-color: var(--color-accent-hover); }

.btn-danger {
  background: var(--color-danger);
  color: #fff;
  border-color: var(--color-danger);
}
.btn-danger:hover { background: var(--color-danger-hover); border-color: var(--color-danger-hover); }

.btn-danger-ghost {
  background: transparent;
  color: var(--color-danger);
  border-color: var(--color-danger);
}
.btn-danger-ghost:hover {
  background: var(--color-danger-bg);
}

main {
  max-width: 960px;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 4rem;
}

/* ── Breadcrumb ─────────────────────────────────────────────── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
  list-style: none;
}
.breadcrumb a {
  color: var(--color-text-muted);
  text-decoration: none;
}
.breadcrumb a:hover { color: var(--color-accent); text-decoration: underline; }
.breadcrumb a:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}
.breadcrumb .sep { user-select: none; }

/* ── Preview card ───────────────────────────────────────────── */
.preview-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
}

.preview-image-wrap {
  position: relative;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 420px;
  overflow: hidden;
}

.preview-image-wrap img {
  width: 100%;
  height: 420px;
  object-fit: cover;
  display: block;
}

.image-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: rgba(0,0,0,.55);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,.1);
  color: #fff;
  font-size: .75rem;
  font-weight: 600;
  padding: .25rem .6rem;
  border-radius: 99px;
  letter-spacing: .04em;
  text-transform: uppercase;
}

/* ── Image metadata & actions ───────────────────────────────── */
.preview-body {
  padding: 1.5rem 2rem 2rem;
}

.preview-meta {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.25rem;
}

.preview-title { font-size: 1.375rem; font-weight: 700; line-height: 1.3; }
.preview-subtitle { font-size: .875rem; color: var(--color-text-muted); margin-top: .25rem; }

.preview-tags {
  display: flex;
  flex-wrap: wrap;
  gap: .5rem;
  margin-bottom: 1.5rem;
  list-style: none;
}

.tag {
  display: inline-block;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: .75rem;
  font-weight: 500;
  padding: .2rem .65rem;
  border-radius: 99px;
}

.preview-stats {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 1rem 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 1.5rem;
}

.stat { display: flex; flex-direction: column; gap: .125rem; }
.stat-label { font-size: .6875rem; text-transform: uppercase; letter-spacing: .06em; color: var(--color-text-muted); }
.stat-value { font-size: .9375rem; font-weight: 600; }

.preview-actions {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
  align-items: center;
}

.preview-actions .btn-danger-ghost {
  margin-left: auto;
}

/* ── Modal backdrop ─────────────────────────────────────────── */
dialog {
  padding: 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  color: var(--color-text);
  box-shadow: var(--shadow-dialog);
  max-width: min(480px, calc(100vw - 2rem));
  width: 100%;
  /* override UA default positioning */
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  margin: 0;
  /* hidden state */
  opacity: 0;
  scale: .96;
  pointer-events: none;
  transition: opacity 200ms ease, scale 200ms ease, display 200ms ease allow-discrete, overlay 200ms ease allow-discrete;
}

dialog[open] {
  opacity: 1;
  scale: 1;
  pointer-events: auto;
}

/* entry animation using @starting-style */
@starting-style {
  dialog[open] {
    opacity: 0;
    scale: .96;
  }
}

dialog::backdrop {
  background: rgba(0, 0, 0, 0);
  backdrop-filter: blur(0px);
  transition: background 200ms ease, backdrop-filter 200ms ease,
              display 200ms ease allow-discrete, overlay 200ms ease allow-discrete;
}

dialog[open]::backdrop {
  background: rgba(0, 0, 0, .65);
  backdrop-filter: blur(4px);
}

@starting-style {
  dialog[open]::backdrop {
    background: rgba(0, 0, 0, 0);
    backdrop-filter: blur(0px);
  }
}

/* ── Dialog content ─────────────────────────────────────────── */
.dialog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem 1.5rem 0;
}

.dialog-icon-wrap {
  flex-shrink: 0;
  width: 2.75rem;
  height: 2.75rem;
  background: var(--color-danger-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-danger);
}

.dialog-close {
  flex-shrink: 0;
  background: transparent;
  border: 1px solid var(--color-border);
  color: var(--color-text-muted);
  width: 2rem;
  height: 2rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
  margin-top: .125rem;
}
.dialog-close:hover {
  background: var(--color-surface-2);
  color: var(--color-text);
  border-color: var(--color-text-muted);
}
.dialog-close:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

.dialog-body { padding: 1rem 1.5rem; }

.dialog-title {
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: .375rem;
}

.dialog-desc {
  font-size: .875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog-image-preview {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: .875rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  margin-top: 1.25rem;
}

.dialog-thumb {
  width: 3.5rem;
  height: 3.5rem;
  object-fit: cover;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  border: 1px solid var(--color-border);
}

.dialog-image-info { min-width: 0; }
.dialog-image-name {
  font-size: .875rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dialog-image-size {
  font-size: .75rem;
  color: var(--color-text-muted);
  margin-top: .125rem;
}

.dialog-footer {
  display: flex;
  gap: .75rem;
  justify-content: flex-end;
  padding: 1.25rem 1.5rem 1.5rem;
  border-top: 1px solid var(--color-border);
}

/* ── Responsive ─────────────────────────────────────────────── */
@media (max-width: 600px) {
  .app-header { padding: 1rem; }
  main { padding: 1.5rem 1rem 3rem; }
  .preview-body { padding: 1.25rem 1.25rem 1.5rem; }
  .preview-image-wrap img { height: 260px; }
  .preview-title { font-size: 1.125rem; }
  .preview-actions .btn-danger-ghost { margin-left: 0; }
  .dialog-footer { flex-direction: column-reverse; }
  .dialog-footer .btn { width: 100%; justify-content: center; }
}

/* ── Focus visible polyfill ─────────────────────────────────── */
:focus:not(:focus-visible) { outline: none; }

/* ── Live region ────────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

