  const elem = document.createElement(tag);
  const { className, id, attrs, on, html } = props;
  if (className) elem.className = className;
  if (id) elem.id = id;
  if (html) { elem.innerHTML = html; return elem; }
  if (attrs) Object.entries(attrs).forEach(([k, v]) => {
