const el = (tag, props = {}, ...children) => {
  const elem = document.createElement(tag);
  const { className, id, attrs, on, html } = props;
  if (className) elem.className = className;
  if (id) elem.id = id;
  if (html) { elem.innerHTML = html; return elem; }
  if (attrs) Object.entries(attrs).forEach(([k, v]) => {
    if (v === false || v == null) return;
    if (v === true) elem.setAttribute(k, '');
    else elem.setAttribute(k, v);
  });
  if (on) Object.entries(on).forEach(([ev, fn]) => elem.addEventListener(ev, fn));
  children.flat(Infinity).forEach(child => {
    if (child == null) return;
    elem.append(typeof child === 'string' ? document.createTextNode(child) : child);
  });
  return elem;
};

