+  const title = el('h2', { className: 'dialog-title', id: 'dialog-title' },
+    'Delete image?'
+  );
+  const desc = el('p', { className: 'dialog-desc', id: 'dialog-desc' },
+    'This image will be permanently removed from your library. This action cannot be undone.'
+  );
+
+  const thumb = el('img', {
+    className: 'dialog-thumb',
+    attrs: {
+      src: imageData.src,
+      alt: '',   /* decorative — file name already conveys identity */
+      width: '56',
+      height: '56',
+    },
+  });
+
+  const imagePreview = el('div', { className: 'dialog-image-preview' },
+    thumb,
+    el('div', { className: 'dialog-image-info' },
+      el('div', { className: 'dialog-image-name' }, imageData.name),
+      el('div', { className: 'dialog-image-size' }, imageData.size),
+    ),
+  );
+
+  const body = el('div', { className: 'dialog-body' }, title, desc, imagePreview);
+
+  /* footer */
+  const cancelBtn = el('button', {
+    className: 'btn btn-ghost',
+    attrs: { type: 'button' },
+  }, 'Cancel');
+
+  const confirmBtn = el('button', {
+    className: 'btn btn-danger',
+    attrs: { type: 'button' },
+  }, el('span', { html: icons.trash }), 'Delete image');
+
+  const footer = el('div', { className: 'dialog-footer' }, cancelBtn, confirmBtn);
+
+  dialog.append(header, body, footer);
+
+  /* ── Focus trap ─────────────────────────────────────────── */
+  const getFocusable = () => [
+    ...dialog.querySelectorAll(
+      'button:not([disabled]), [href], input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])'
